// Deterministic model-selection engine. No LLM sits in the decision path.
//
// Every number in CANDIDATES is a CONFIGURED PRIOR, not a measurement:
//   price_*_usd_per_mtok  vendor list price captured at build time. Operators MUST
//                         re-check these. See docs/ROI-METHODOLOGY.md.
//   quality_prior         operator-set 0..1 prior. Replace with measured evaluation
//                         scores once the benchmark harness has been run.
//   latency_prior_ms      seed value only. Real latency is measured per call and
//                         written to the agentic_router_telemetry data table.
const CANDIDATES = [
  {
    key: 'gemini', provider: 'google', model: 'models/gemini-3-flash-preview',
    branch: 'gemini', locality: 'cloud',
    price_in_usd_per_mtok: 0.30, price_out_usd_per_mtok: 2.50,
    quality_prior: 0.80, latency_prior_ms: 1500,
    json_mode: true, tool_calls: true, context_tokens: 1000000, vision: true
  },
  {
    key: 'openai', provider: 'openai', model: 'gpt-5-mini',
    branch: 'openai', locality: 'cloud',
    price_in_usd_per_mtok: 0.25, price_out_usd_per_mtok: 2.00,
    quality_prior: 0.85, latency_prior_ms: 2600,
    json_mode: true, tool_calls: true, context_tokens: 400000, vision: true
  },
  {
    key: 'anthropic', provider: 'anthropic', model: 'claude-sonnet-5',
    branch: 'anthropic', locality: 'cloud',
    price_in_usd_per_mtok: 3.00, price_out_usd_per_mtok: 15.00,
    quality_prior: 0.93, latency_prior_ms: 3400,
    json_mode: true, tool_calls: true, context_tokens: 200000, vision: true
  }
  // To serve privacy=local_only, register a local candidate here, for example
  // { key: 'ollama', provider: 'ollama', model: 'qwen3:8b', locality: 'local', ... }
  // and add a matching branch to the Provider Switch + an Ollama chain node.
];

// Weight profiles per objective. Each profile sums to 1.0.
const WEIGHTS = {
  quality:  { quality: 0.75, cost: 0.05, latency: 0.20 },
  balanced: { quality: 0.45, cost: 0.30, latency: 0.25 },
  cost:     { quality: 0.20, cost: 0.65, latency: 0.15 },
  latency:  { quality: 0.25, cost: 0.15, latency: 0.60 }
};

// Hard capability requirements per task type, applied before scoring.
const TASK_REQUIREMENTS = {
  extraction:     { json_mode: true, min_quality: 0.78 },
  verification:   { json_mode: true, min_quality: 0.78 },
  classification: { json_mode: true, min_quality: 0.70 },
  reasoning:      { min_quality: 0.84 },
  research:       { min_quality: 0.78, min_context_tokens: 200000 },
  code:           { min_quality: 0.84 },
  summarization:  { min_quality: 0.70 },
  conversation:   { min_quality: 0.70 },
  general:        { min_quality: 0.70 }
};

const req = $json;
const objective = WEIGHTS[req.objective] ? req.objective : 'balanced';
const weights = WEIGHTS[objective];
const taskReq = TASK_REQUIREMENTS[req.task_type] || TASK_REQUIREMENTS.general;

// Token estimate: roughly 4 characters per token. Explicitly an ESTIMATE - the
// n8n LangChain chain nodes do not surface provider-reported token counts.
const inputChars = String(req.input || '').length + String(req.system_prompt || '').length;
const tokensInEst = Math.max(1, Math.ceil(inputChars / 4));
const tokensOutEst = Math.max(64, Math.ceil(tokensInEst * 0.5));

const policyFlags = [];
const rejected = [];

// ---- Gate 1: privacy. NEVER bypassable, not even by force_provider. -------
// local_only means the payload must never leave the host. With no local
// candidate registered the router refuses instead of silently downgrading.
let privacyPool = CANDIDATES.slice();
if (req.privacy === 'local_only') {
  privacyPool.forEach(function (c) {
    if (c.locality !== 'local') { rejected.push({ key: c.key, reason: 'privacy:local_only' }); }
  });
  privacyPool = privacyPool.filter(function (c) { return c.locality === 'local'; });
  policyFlags.push('privacy_local_only');
}

// ---- Gate 2: task capability. Bypassable by an explicit force_provider. ---
const capable = [];
privacyPool.forEach(function (c) {
  if (taskReq.json_mode && !c.json_mode) { rejected.push({ key: c.key, reason: 'requires_json_mode' }); return; }
  if (taskReq.min_quality && c.quality_prior < taskReq.min_quality) { rejected.push({ key: c.key, reason: 'below_min_quality' }); return; }
  if (taskReq.min_context_tokens && c.context_tokens < taskReq.min_context_tokens) { rejected.push({ key: c.key, reason: 'context_too_small' }); return; }
  capable.push(c);
});

// ---- Scoring --------------------------------------------------------------
function blendedPrice(c) {
  return (c.price_in_usd_per_mtok * tokensInEst + c.price_out_usd_per_mtok * tokensOutEst) / 1000000;
}

// Lower is better for price and latency, so invert into a 0..1 goodness score.
function invNorm(v, lo, hi) { return (hi - lo) < 1e-12 ? 1 : (hi - v) / (hi - lo); }

function rank(pool) {
  const priced = pool.map(function (c) { return { c: c, price: blendedPrice(c) }; });
  const prices = priced.map(function (p) { return p.price; });
  const lats = pool.map(function (c) { return c.latency_prior_ms; });
  const maxPrice = prices.length ? Math.max.apply(null, prices) : 1;
  const minPrice = prices.length ? Math.min.apply(null, prices) : 0;
  const maxLat = lats.length ? Math.max.apply(null, lats) : 1;
  const minLat = lats.length ? Math.min.apply(null, lats) : 0;
  return priced.map(function (p) {
    const costScore = invNorm(p.price, minPrice, maxPrice);
    const latScore = invNorm(p.c.latency_prior_ms, minLat, maxLat);
    const total = weights.quality * p.c.quality_prior + weights.cost * costScore + weights.latency * latScore;
    return {
      key: p.c.key, provider: p.c.provider, model: p.c.model, branch: p.c.branch,
      score: Math.round(total * 10000) / 10000,
      quality_prior: p.c.quality_prior,
      cost_score: Math.round(costScore * 10000) / 10000,
      latency_score: Math.round(latScore * 10000) / 10000,
      estimated_cost_usd: Math.round(p.price * 1000000) / 1000000
    };
  }).sort(function (a, b) { return b.score - a.score; });
}

const ranked = rank(capable);
const rankedIgnoringCapability = rank(privacyPool);

// ---- Caller override (used by the benchmark harness) ----------------------
// Forcing bypasses the capability gate so a benchmark can measure any provider
// on any task. It can never bypass the privacy gate above.
let chosen = ranked.length ? ranked[0] : null;
let reason = '';
if (req.force_provider) {
  const forced = rankedIgnoringCapability.filter(function (r) { return r.key === req.force_provider; })[0];
  if (forced) {
    const wasCapable = ranked.filter(function (r) { return r.key === req.force_provider; }).length > 0;
    chosen = forced;
    reason = 'forced by caller (force_provider=' + req.force_provider + ')'
      + (wasCapable ? '' : ' - capability gate bypassed for this task type');
    policyFlags.push('forced_provider');
    if (!wasCapable) { policyFlags.push('capability_gate_bypassed'); }
  } else {
    policyFlags.push('forced_provider_unavailable');
  }
}

if (!chosen) {
  const blockReason = req.privacy === 'local_only'
    ? 'No local model provider is registered. Add a candidate with locality "local" and a matching switch branch to serve privacy=local_only requests.'
    : 'No registered candidate satisfies the capability requirements for task_type=' + req.task_type + '.';
  return {
    json: Object.assign({}, req, {
      routed: false,
      branch: 'blocked',
      block_reason: blockReason,
      policy_flags: policyFlags,
      rejected_candidates: rejected,
      candidate_scores: ranked,
      tokens_in_est: tokensInEst,
      tokens_out_est: tokensOutEst
    })
  };
}

if (!reason) {
  reason = 'objective=' + objective + ' weights(quality=' + weights.quality + ', cost=' + weights.cost
    + ', latency=' + weights.latency + '); winning score ' + chosen.score
    + ' (quality_prior=' + chosen.quality_prior + ', cost_score=' + chosen.cost_score
    + ', latency_score=' + chosen.latency_score + ')';
}
const fallbackPick = rankedIgnoringCapability.filter(function (r) { return r.key !== chosen.key; })[0];

return {
  json: Object.assign({}, req, {
    routed: true,
    branch: chosen.branch,
    selected_provider: chosen.provider,
    selected_model: chosen.model,
    selected_key: chosen.key,
    reason: reason,
    fallback: fallbackPick ? (fallbackPick.provider + '/' + fallbackPick.model) : 'google/models/gemini-3.1-flash-lite',
    estimated_cost_usd: chosen.estimated_cost_usd,
    cost_basis: 'configured_list_price_estimate',
    tokens_in_est: tokensInEst,
    tokens_out_est: tokensOutEst,
    candidate_scores: ranked.length ? ranked : rankedIgnoringCapability,
    rejected_candidates: rejected,
    policy_flags: policyFlags,
    weights_used: weights
  })
};

// Builds the public router response contract.
// MEASURED and ESTIMATED values live under separate keys on purpose, so that
// downstream READMEs and benchmark files can never present an estimate as a
// measurement.
const decision = $('Route Decision Engine').first().json;
const req = $('Normalise Request').first().json;
const res = $json;

const endedAtMs = Date.now();
const startedAtMs = Number(req.started_at_ms || 0);
const latencyMs = startedAtMs > 0 ? (endedAtMs - startedAtMs) : null;

const text = typeof res.text === 'string' ? res.text : (res.output || res.response || '');
const stage = res.route_stage || 'primary';
const blocked = stage === 'blocked';
const usedFallback = stage === 'fallback';

const outChars = String(text || '').length;
const tokensOutEst = Math.max(0, Math.ceil(outChars / 4));
const tokensInEst = decision.tokens_in_est || 0;

// Vendor list prices, USD per million tokens, captured at build time.
// Operators must re-verify. See docs/ROI-METHODOLOGY.md.
const PRICES = {
  'google/models/gemini-3-flash-preview': { in: 0.30, out: 2.50 },
  'google/models/gemini-3.1-flash-lite': { in: 0.10, out: 0.40 },
  'openai/gpt-5-mini': { in: 0.25, out: 2.00 },
  'anthropic/claude-sonnet-5': { in: 3.00, out: 15.00 }
};

const providerUsed = usedFallback ? 'google' : (decision.selected_provider || null);
const modelUsed = usedFallback ? 'models/gemini-3.1-flash-lite' : (decision.selected_model || null);
const priceKey = (providerUsed && modelUsed) ? (providerUsed + '/' + modelUsed) : null;
const price = (priceKey && PRICES[priceKey]) ? PRICES[priceKey] : null;
const estimatedCost = price
  ? Math.round(((price.in * tokensInEst + price.out * tokensOutEst) / 1000000) * 1000000) / 1000000
  : 0;

const succeeded = !blocked && !!text && res.call_status !== 'failed';

return {
  json: {
    request_id: req.request_id,
    source_workflow: req.source_workflow,
    run_label: req.run_label,
    ok: succeeded,
    status: blocked ? 'policy_blocked' : (succeeded ? 'ok' : 'failed'),
    output: text,
    selected_provider: providerUsed,
    selected_model: modelUsed,
    reason: blocked ? decision.block_reason : decision.reason,
    fallback: decision.fallback || null,
    fallback_used: usedFallback,
    route_stage: stage,
    latency_ms: latencyMs,
    measured: { latency_ms: latencyMs, output_chars: outChars },
    estimated: {
      tokens_in: tokensInEst,
      tokens_out: tokensOutEst,
      cost_usd: estimatedCost,
      cost_basis: 'configured list price; tokens derived from characters/4'
    },
    estimated_cost_usd: estimatedCost,
    task_type: req.task_type,
    objective: req.objective,
    privacy: req.privacy,
    policy_flags: decision.policy_flags || [],
    candidate_scores: decision.candidate_scores || [],
    rejected_candidates: decision.rejected_candidates || [],
    error: (blocked || !succeeded)
      ? (res.error || decision.block_reason || 'empty model response')
      : null
  }
};

// Reproducible benchmark matrix: every registered provider runs every task.
// Each case carries a DETERMINISTIC check so the scores below are measured,
// not asserted. Nothing here contains real customer data.
const PROVIDERS = ['gemini', 'openai', 'anthropic'];

const CASES = [
  {
    case_id: 'reasoning-1',
    task_type: 'reasoning',
    objective: 'quality',
    check: 'contains_all',
    system_prompt: 'Answer in at most three sentences. Be precise.',
    input: 'In information retrieval, what is the trade-off between precision and recall? Name both terms explicitly.'
  },
  {
    case_id: 'extraction-1',
    task_type: 'extraction',
    objective: 'balanced',
    check: 'json_keys',
    system_prompt: 'You output ONLY raw JSON. No markdown fences, no prose, no explanation.',
    input: 'Extract the invoice fields as a JSON object with exactly the keys invoice_number, vendor, total, currency. Source text: "Invoice INV-2043 from Northwind Traders. Amount due: 1240.50 EUR."'
  },
  {
    case_id: 'summarization-1',
    task_type: 'summarization',
    objective: 'cost',
    check: 'grounded_no_fabrication',
    system_prompt: 'Summarise strictly from the source. Do not introduce facts that are not in the source.',
    input: 'Summarise in under 60 words using only the source. SOURCE: "The Halifax bridge was resurfaced in 2019. Traffic volume fell 12 percent in 2020 and recovered to 2018 levels by 2022. No tolls were introduced."'
  }
];

const runId = 'bench-' + $execution.id;
const rows = [];

CASES.forEach(function (c) {
  PROVIDERS.forEach(function (p) {
    rows.push({
      json: {
        run_id: runId,
        case_id: c.case_id,
        check: c.check,
        task_type: c.task_type,
        objective: c.objective,
        privacy: 'standard',
        system_prompt: c.system_prompt,
        input: c.input,
        force_provider: p,
        source_workflow: '02-benchmark-harness',
        run_label: c.case_id + '::' + c.check + '::' + p
      }
    });
  });
});

return rows;

// Scores the benchmark with DETERMINISTIC checks and reports only measured
// values. Latency is measured; cost is an estimate and is labelled as such.
//
// n8n's Execute Sub-workflow node returns the child's output wrapped in an
// extra { json: ... } envelope, so unwrap defensively before reading fields.
const results = $input.all().map(function (i) {
  return (i.json && i.json.json) ? i.json.json : i.json;
});

function stripFences(s) {
  return String(s || '').replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
}

function checkContainsAll(text, needles) {
  const lower = String(text || '').toLowerCase();
  const missing = needles.filter(function (n) { return lower.indexOf(n.toLowerCase()) === -1; });
  return { pass: missing.length === 0, detail: missing.length ? ('missing: ' + missing.join(', ')) : 'all required terms present' };
}

function checkJsonKeys(text, keys) {
  let parsed = null;
  try { parsed = JSON.parse(stripFences(text)); } catch (e) { return { pass: false, detail: 'not parseable as JSON' }; }
  if (!parsed || typeof parsed !== 'object') { return { pass: false, detail: 'parsed value is not an object' }; }
  const missing = keys.filter(function (k) { return !(k in parsed); });
  return { pass: missing.length === 0, detail: missing.length ? ('missing keys: ' + missing.join(', ')) : 'schema satisfied' };
}

function checkGrounded(text, facts) {
  const s = String(text || '');
  const words = s.split(/\s+/).filter(function (w) { return w.length > 0; });
  const present = facts.filter(function (f) { return s.indexOf(f) !== -1; });
  // Fabrication probe: tokens that do NOT appear in the source must not appear here.
  const forbidden = ['2021', '2023', '2024', 'GBP', 'USD'];
  const hallucinated = forbidden.filter(function (f) { return s.indexOf(f) !== -1; });
  const pass = present.length >= 2 && hallucinated.length === 0 && words.length > 0 && words.length <= 90;
  return {
    pass: pass,
    detail: 'grounded_facts=' + present.length + '/' + facts.length
      + '; fabricated_tokens=' + (hallucinated.length ? hallucinated.join(',') : 'none')
      + '; words=' + words.length
  };
}

const EXPECT = {
  'reasoning-1': ['precision', 'recall'],
  'extraction-1': ['invoice_number', 'vendor', 'total', 'currency'],
  'summarization-1': ['2019', '2020', '2022']
};

const rows = results.map(function (r) {
  const parts = String(r.run_label || '').split('::');
  const caseId = parts[0] || 'unknown';
  const check = parts[1] || 'none';
  const forced = parts[2] || (r.selected_provider || 'unknown');
  const expect = EXPECT[caseId] || [];
  let verdict = { pass: false, detail: 'no check registered for ' + caseId };
  if (r.ok) {
    if (check === 'contains_all') { verdict = checkContainsAll(r.output, expect); }
    else if (check === 'json_keys') { verdict = checkJsonKeys(r.output, expect); }
    else if (check === 'grounded_no_fabrication') { verdict = checkGrounded(r.output, expect); }
  } else {
    verdict = { pass: false, detail: 'call failed: ' + (r.error || 'unknown') };
  }
  return {
    case_id: caseId,
    check: check,
    requested_provider: forced,
    served_by_provider: r.selected_provider || null,
    served_by_model: r.selected_model || null,
    call_ok: !!r.ok,
    fallback_used: !!r.fallback_used,
    check_pass: verdict.pass,
    check_detail: verdict.detail,
    latency_ms_measured: typeof r.latency_ms === 'number' ? r.latency_ms : null,
    output_chars_measured: r.measured ? r.measured.output_chars : null,
    estimated_cost_usd: r.estimated_cost_usd
  };
});

function pct(list, p) {
  const xs = list.filter(function (v) { return typeof v === 'number' && isFinite(v); }).sort(function (a, b) { return a - b; });
  if (!xs.length) { return null; }
  const idx = Math.min(xs.length - 1, Math.max(0, Math.ceil((p / 100) * xs.length) - 1));
  return xs[idx];
}

const byProvider = {};
rows.forEach(function (r) {
  const key = r.requested_provider;
  if (!byProvider[key]) { byProvider[key] = { provider: key, runs: 0, ok: 0, checks_passed: 0, fallbacks: 0, latencies: [], cost: 0 }; }
  const p = byProvider[key];
  p.runs += 1;
  if (r.call_ok) { p.ok += 1; }
  if (r.check_pass) { p.checks_passed += 1; }
  if (r.fallback_used) { p.fallbacks += 1; }
  if (typeof r.latency_ms_measured === 'number') { p.latencies.push(r.latency_ms_measured); }
  p.cost += Number(r.estimated_cost_usd || 0);
});

const summary = Object.keys(byProvider).map(function (k) {
  const p = byProvider[k];
  return {
    requested_provider: p.provider,
    runs: p.runs,
    call_success_rate: p.runs ? Math.round((p.ok / p.runs) * 100) / 100 : null,
    check_pass_rate: p.runs ? Math.round((p.checks_passed / p.runs) * 100) / 100 : null,
    fallback_rate: p.runs ? Math.round((p.fallbacks / p.runs) * 100) / 100 : null,
    latency_ms_p50_measured: pct(p.latencies, 50),
    latency_ms_p95_measured: pct(p.latencies, 95),
    latency_ms_min_measured: p.latencies.length ? Math.min.apply(null, p.latencies) : null,
    latency_ms_max_measured: p.latencies.length ? Math.max.apply(null, p.latencies) : null,
    total_estimated_cost_usd: Math.round(p.cost * 1000000) / 1000000
  };
}).sort(function (a, b) { return String(a.requested_provider).localeCompare(String(b.requested_provider)); });

return [{
  json: {
    benchmark: 'router-provider-matrix-v1',
    generated_at: new Date().toISOString(),
    n8n_execution_id: $execution.id,
    note: 'latency_ms_* are MEASURED wall-clock times inside n8n and include network, provider queueing and retry time. estimated_cost_usd values are ESTIMATES from configured list prices with tokens approximated as characters/4.',
    sample_size_caveat: 'One run per (task, provider) cell. p50/p95 over 3 samples per provider are indicative only, not statistically stable.',
    total_runs: rows.length,
    provider_summary: summary,
    runs: rows
  }
}];

